_ALLOWED_NAME_CHARS = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_"
)
_DIGIT_CHARS = frozenset("0123456789")


def _is_valid_name(name: str) -> bool:
    return bool(name) and all(ch in _ALLOWED_NAME_CHARS for ch in name)


def match_route(pattern: str, path: str):
    if (
        not isinstance(pattern, str)
        or not isinstance(path, str)
        or not pattern.startswith("/")
        or not path.startswith("/")
    ):
        raise ValueError("pattern and path must be strings starting with '/'")

    pattern_segments = pattern[1:].split("/")
    path_segments = path[1:].split("/")

    segments = []
    used_names = set()

    for seg in pattern_segments:
        if seg.startswith(":"):
            if seg.endswith("?"):
                kind = "opt"
                name = seg[1:-1]
            else:
                kind = "param"
                name = seg[1:]
        elif seg.startswith("#"):
            kind = "int"
            name = seg[1:]
        elif seg.startswith("*"):
            kind = "star"
            name = seg[1:]
        else:
            segments.append(("lit", seg))
            continue

        if not _is_valid_name(name):
            raise ValueError(f"invalid name in pattern segment: {seg!r}")
        if name in used_names:
            raise ValueError(f"duplicate name in pattern: {name!r}")

        used_names.add(name)
        segments.append((kind, name))

    m = len(segments)
    n = len(path_segments)

    nonempty = [seg != "" for seg in path_segments]
    is_digit = [False] * n
    for i, seg in enumerate(path_segments):
        if nonempty[i] and all(ch in _DIGIT_CHARS for ch in seg):
            is_digit[i] = True

    # can[i][j] is true iff pattern[i:] can match path_segments[j:].
    can = [None] * (m + 1)
    can[m] = bytearray(n + 1)
    can[m][n] = 1

    for i in range(m - 1, -1, -1):
        kind, value = segments[i]
        next_row = can[i + 1]
        row = bytearray(n + 1)

        if kind == "lit":
            literal = value
            for j in range(n):
                if path_segments[j] == literal and next_row[j + 1]:
                    row[j] = 1

        elif kind == "param":
            for j in range(n):
                if nonempty[j] and next_row[j + 1]:
                    row[j] = 1

        elif kind == "int":
            for j in range(n):
                if is_digit[j] and next_row[j + 1]:
                    row[j] = 1

        elif kind == "opt":
            row[n] = next_row[n]
            for j in range(n):
                if next_row[j] or (nonempty[j] and next_row[j + 1]):
                    row[j] = 1

        else:  # kind == "star"
            suffix_ok = next_row[n]
            row[n] = suffix_ok
            for j in range(n - 1, -1, -1):
                if not suffix_ok and next_row[j]:
                    suffix_ok = 1
                row[j] = suffix_ok

        can[i] = row

    if not can[0][0]:
        return None

    captures = {}
    j = 0

    for i, (kind, value) in enumerate(segments):
        if kind == "opt":
            if can[i + 1][j]:
                captures[value] = None
            else:
                captures[value] = path_segments[j]
                j += 1

        elif kind == "star":
            next_row = can[i + 1]
            k = 0
            while not next_row[j + k]:
                k += 1
            captures[value] = path_segments[j:j + k]
            j += k

        elif kind == "param":
            captures[value] = path_segments[j]
            j += 1

        elif kind == "int":
            captures[value] = int(path_segments[j])
            j += 1

        else:  # literal
            j += 1

    return captures
