def ferry_plan(routes: list[tuple[str, str, int, int, int]], src: str, dst: str, t0: int):
    if src == dst:
        return (t0, 0)

    routes = list(routes)

    ports = {src, dst}
    for a, b, first, every, duration in routes:
        if a != b:
            ports.add(a)
            ports.add(b)

    idx = {p: i for i, p in enumerate(ports)}
    n = len(idx)

    outgoing = [[] for _ in range(n)]
    for a, b, first, every, duration in routes:
        if a == b:
            continue
        outgoing[idx[a]].append((idx[b], first, every, duration))

    s = idx[src]
    d = idx[dst]

    # Any optimal walk can be simplified: if a port is visited twice,
    # replace the loop by waiting at the first visit. Thus a simple walk
    # with at most n - 1 ferries is sufficient.
    INF = 10 ** 30
    dp = [INF] * n
    dp[s] = t0

    best_time = INF
    best_ferries = 0

    for ferries in range(1, n):
        ndp = [INF] * n
        any_reached = False

        for u, t in enumerate(dp):
            if t == INF:
                continue

            for v, first, every, duration in outgoing[u]:
                if t <= first:
                    departure = first
                else:
                    departure = first + ((t - first + every - 1) // every) * every

                arrival = departure + duration
                if arrival < ndp[v]:
                    ndp[v] = arrival
                    any_reached = True

        arrival_at_dst = ndp[d]
        if arrival_at_dst < best_time:
            best_time = arrival_at_dst
            best_ferries = ferries
        # If arrival_at_dst == best_time, the current ferry count is larger
        # than the previously recorded count for that same time.

        dp = ndp
        if not any_reached:
            break

    if best_time == INF:
        return None

    return (best_time, best_ferries)
